<template>
	<span :data-timestamp="timestamp * 1000" :title="title">{{ formatted }}</span>
</template>

<script>
import { detailedRelativeDatetime } from '../util/relativeDatetime.js'
import { formatInUserTimezone } from '../util/userTimezone.js'

export default {
	name: 'Moment',
	props: {
		timestamp: {
			type: Number,
			required: true,
		},

		format: {
			type: String,
			default: 'LLL',
		},
	},

	computed: {
		title() {
			return formatInUserTimezone(this.timestamp, this.format)
		},

		formatted() {
			return detailedRelativeDatetime(new Date(this.timestamp * 1000))
		},
	},
}
</script>
